import { cn } from '@cascivo/core/pure'
import { builtin, formatNumber, t } from '@cascivo/i18n'
import type { CSSProperties, HTMLAttributes } from 'react'
import styles from './context-meter.module.css'

export interface ContextMeterProps extends HTMLAttributes<HTMLDivElement> {
  value: number
  max: number
  /**
   * The meter’s name, shown above the bar.
   *
   * @defaultValue `Context`
   * @see the component manifest
   */
  label?: string
  labels?: {
    usage?: string
  }
}

/** Fraction at which the meter warns, and at which it reads as full. */
const HIGH = 0.8
const FULL = 0.95

export function ContextMeter({
  value,
  max,
  label,
  labels,
  className,
  style,
  ...props
}: ContextMeterProps) {
  const fraction = max > 0 ? Math.min(Math.max(value / max, 0), 1) : 0
  const level = fraction >= FULL ? 'full' : fraction >= HIGH ? 'high' : 'normal'
  const percent = formatNumber(fraction, { style: 'percent', maximumFractionDigits: 0 })
  const name = label ?? t(builtin.contextMeter.label)
  const params = { used: formatNumber(value), max: formatNumber(max), percent }
  const usage =
    labels?.usage?.replace(
      /\{(used|max|percent)\}/g,
      (_, key: keyof typeof params) => params[key],
    ) ?? t(builtin.contextMeter.usage, params)

  return (
    <div
      role="meter"
      aria-label={name}
      aria-valuenow={value}
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuetext={usage}
      data-level={level}
      className={cn(styles['meter'], className as string | undefined)}
      style={{ ['--_fill' as string]: String(fraction), ...style } as CSSProperties}
      {...props}
    >
      {/* The visible line repeats the accessible name and value text, so it is hidden from
          assistive tech rather than read twice. */}
      <div className={styles['header']} aria-hidden="true">
        <span className={styles['label']}>{name}</span>
        <span className={styles['value']}>
          {formatNumber(value, { notation: 'compact' })} /{' '}
          {formatNumber(max, { notation: 'compact' })}
        </span>
      </div>
      <div className={styles['track']} aria-hidden="true">
        <div className={styles['fill']} />
      </div>
    </div>
  )
}

@layer cascivo.component {
  .meter {
    --_meter-color: var(--cascivo-color-ai);
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
    min-inline-size: 8rem;
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-xs);
    color: var(--cascivo-color-text-muted);

    &[data-level='high'] {
      --_meter-color: var(--cascivo-color-warning);
    }

    &[data-level='full'] {
      --_meter-color: var(--cascivo-color-destructive);
    }
  }

  .header {
    display: flex;
    justify-content: space-between;
    gap: var(--cascivo-space-2);
  }

  .value {
    font-variant-numeric: tabular-nums;
    color: var(--cascivo-color-text);
  }

  .track {
    overflow: hidden;
    block-size: 0.25rem;
    border-radius: var(--cascivo-radius-full);
    background-color: var(--cascivo-color-bg-subtle);
  }

  /* Logical sizing, so the fill grows from the inline start in either direction. Not
     transitioned: a token count jumps rather than glides. */
  .fill {
    inline-size: calc(var(--_fill, 0) * 100%);
    block-size: 100%;
    background-color: var(--_meter-color);
  }
}

@media (forced-colors: active) {
  .track {
    border: 1px solid CanvasText;
  }

  .fill {
    background-color: Highlight;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'ContextMeter',
  description:
    'How much of a model’s context window a conversation has used — "12K / 200K" with a bar that warns as it fills',
  category: 'feedback',
  clientJs: 'none',
  states: ['normal', 'high', 'full'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'value',
      description: 'Tokens used so far.',
      type: 'number',
      required: true,
    },
    {
      name: 'max',
      description: 'The context window size, in tokens.',
      type: 'number',
      required: true,
    },
    {
      name: 'label',
      nameVisibility: 'visible',
      description: 'The meter’s name, shown above the bar.',
      type: 'string',
      required: false,
      default: 'Context',
    },
    {
      name: 'labels',
      description:
        'Overrides for the component’s user-visible strings (i18n). `usage` is the spoken value and may contain `{used}`, `{max}` and `{percent}`.',
      type: '{ usage?: string }',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-ai',
    '--cascivo-color-warning',
    '--cascivo-color-destructive',
    '--cascivo-color-bg-subtle',
    '--cascivo-color-text',
    '--cascivo-color-text-muted',
    '--cascivo-radius-full',
  ],
  accessibility: { role: 'meter', wcag: '2.2-AA', keyboard: [], forcedColors: true },
  examples: [
    { title: 'Plenty left', code: '<ContextMeter value={12400} max={200000} />' },
    { title: 'Nearly full', code: '<ContextMeter value={192000} max={200000} />' },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['ai', 'context', 'tokens', 'usage', 'meter', 'quota'],
  intent: {
    whenToUse: [
      'Showing how much of the model’s context window a conversation or document has used',
      'Warning before a conversation hits the limit and older turns are dropped',
    ],
    whenNotToUse: [
      'Task progress toward completion — use ProgressBar',
      'Account-level usage and billing quotas with many figures — use Stat or a chart',
    ],
    antiPatterns: [
      {
        bad: 'Colour alone to signal the window is nearly full',
        good: 'Keep the "used / max" figures visible; colour reinforces them',
        why: 'Colour is not perceivable by everyone; the numbers carry the meaning',
      },
    ],
    related: [
      {
        name: 'ProgressBar',
        relationship: 'alternative',
        reason: 'ProgressBar is for progress toward done; a meter measures a level within a range',
      },
      {
        name: 'AiStatus',
        relationship: 'pairs-with',
        reason: 'Both sit in an AI chat’s header or footer',
      },
    ],
    a11yRationale:
      'role="meter" with aria-valuenow/min/max and an aria-valuetext in full words ("12,400 of 200,000 tokens used (6%)"), named by its label. The compact visible line is aria-hidden so it is not read twice. Colour steps to warning at 80% and destructive at 95%, but the figures always carry the meaning',
    flexibility: [
      {
        area: 'label and wording',
        level: 'flexible',
        note: 'Rename via label; reword via labels.usage',
      },
      {
        area: 'thresholds',
        level: 'strict',
        note: 'Warning at 80%, full at 95% — consistent across every meter',
      },
    ],
  },
}
